\begin{theorem}[Optimal quadratic Poisson--Charlier approximation]
\label{p1:thm:main}
Fix \(C>0\). For every \(\varepsilon>0\), there are
positive constants \(c_{C,\varepsilon}\), \(C_{C,\varepsilon}\)
such that, for all sufficiently large \(N\), uniformly over
\((N,L)\) satisfying \eqref{p1:eq:critical},
\begin{equation}
 c_{C,\varepsilon}N^{-4/3-\varepsilon}
 \le \left\|\Law(Z_N)-Q_{\mu_N,\alpha_N}\right\|_1
 \le C_{C,\varepsilon}N^{-4/3+\varepsilon}.
 \label{p1:eq:main}
\end{equation}
The proof is unconditional.
Moreover, \(\mu_N-\lambda_N=O_{C,\varepsilon}(N^{-1+\varepsilon})\).
The reference \(Q_{\mu_N,\alpha_N}\) is a probability measure for
all sufficiently large \(N\).
\end{theorem}

\begin{corollary}[Exact total variation scale]
\label{p1:cor:tv}
Under the same assumptions,
\begin{equation}
 \TV(\Law(Z_N),\Pi_{\lambda_N})
   =\frac{\alpha_N}{4}
       \|\Pi_{\lambda_N}*\Delta^{*2}\|_1
       +O_{C,\varepsilon}(N^{-1+\varepsilon}).
 \label{p1:eq:tv-main}
\end{equation}
Consequently,
\begin{equation}
 \TV(\Law(Z_N),\Pi_{\lambda_N})
 \sim
 \frac{r+2}{72\,2^{r/3}}\,
 \lambda_N^{5/3}
 \|\Pi_{\lambda_N}*\Delta^{*2}\|_1\,
 L N^{-2/3}.
 \label{p1:eq:tv-equiv}
\end{equation}
With \(\Pi_{\mu_N}\) as the uncorrected reference, the
first formula holds with \(\mu_N\) in the difference norm
and error \(O_{C,\varepsilon}(N^{-4/3+\varepsilon})\);
the equivalent \eqref{p1:eq:tv-equiv} is unchanged.
\end{corollary}

\begin{corollary}[An explicit probability reference]
\label{p1:cor:explicit}
For every \(\varepsilon>0\), uniformly in the critical band,
\begin{equation}
 \left\|\Law(Z_N)-\Pi_{\lambda_N}
       -\frac{\widehat\alpha_N}{2}
          \Pi_{\lambda_N}*\Delta^{*2}\right\|_1
       \ll_{C,\varepsilon}N^{-4/5+\varepsilon}.
 \label{p1:eq:explicit-law}
\end{equation}
For all sufficiently large \(N\), the reference
\(Q_{\lambda_N,\widehat\alpha_N}\) is a probability measure.
Its mass at \(k\ge0\) is
\begin{equation}
 e^{-\lambda_N}\frac{\lambda_N^k}{k!}
 \left[
  1+\frac{\widehat\alpha_N}{2}
       \left\{\frac{k(k-1)}{\lambda_N^2}
                    -\frac{2k}{\lambda_N}+1\right\}
 \right].
 \label{p1:eq:explicit-masses}
\end{equation}
All parameters in this reference are determined by \(N,L\).
\end{corollary}

\begin{proposition}[Support and residual mass]\label{p1:arith:hosts}
For every $\varepsilon>0$,
\begin{align}
 \#\{(x,y)\in I_N^2:|x-y|>L,\ \rho(x,y)>0\}
   &\ll_{C,\varepsilon}N^{1+\varepsilon},
       \label{p1:arith:hostbound}\\
 \sum_{\substack{x,y\in I_N,\ |x-y|>L\\(x,y)\ {\rm nonaligned}}}
       (2^{\rho(x,y)}-1)
   &\ll_{C,\varepsilon}N^{1+\varepsilon}.
       \label{p1:arith:nonaligned}
\end{align}
\end{proposition}

\begin{theorem}[Complete pair profile]\label{p1:arith:pairs}
The sums below are over ordered separated pairs in $I_N$:
\begin{align}
 \sum_{|x-y|>L}(2^{\rho(x,y)}-1)
 &=\frac N3\{U_{2,3}(L)+U_{3,4}(L)\}
      +O_{C,\varepsilon}(N^{6/5+\varepsilon}),\label{p1:arith:positiveprofile}\\
 \sum_{|x-y|>L}(\eta(x,y)2^{\rho(x,y)}-1)
 &=\frac N3\{S_{2,3}(L)+S_{3,4}(L)\}
      +O_{C,\varepsilon}(N^{6/5+\varepsilon}).\label{p1:arith:signedprofile}
\end{align}
Writing $\mu_N=\E Z_N$ and $\alpha_N=\operatorname{Var}(Z_N)-\mu_N$, one has
\begin{equation}\label{p1:arith:cumulantexpansion}
 \alpha_N=\frac{\lambda^2}{3N}\{S_{2,3}(L)+S_{3,4}(L)\}
            +O_{C,\varepsilon}(N^{-4/5+\varepsilon}).
\end{equation}
Thus, with $r_3=L\bmod3$,
\begin{equation}\label{p1:arith:leadingphase}
 \alpha_N\sim
 \frac{r_3+2}{18\,2^{r_3/3}}\lambda^{5/3}L N^{-2/3}.
\end{equation}
After the entire first-channel term is removed, the next term is
\begin{equation}\label{p1:arith:secondphase}
 \alpha_N-\frac{\lambda^2}{3N}S_{2,3}(L)
 \sim\frac{r_4+3}{24\,2^{r_4/4}}\lambda^{7/4}L N^{-3/4},
 \qquad r_4=L\bmod4.
\end{equation}
\end{theorem}

\begin{corollary}[The pair input for the expansion]\label{p1:arith:edgefamily}
One has $|\mathcal E_N|=O_C(NB)$ and, for an edge in channel $a:b$,
\[
 \rho(e)\leq L/b+O(1),\qquad q_e\leq p^2 2^{L/b+O(1)}.
\]
Moreover,
\begin{align}
 2\beta_N&=\alpha_N+O_{C,\varepsilon}(N^{-4/5+\varepsilon}),
    \label{p1:arith:edgemass}\\
 \sum_{\substack{x,y\in G_N,\ x\ne y\\\{x,y\}\notin\mathcal E_N}}
   |\E[(J_x-p)(J_y-p)]|
 &\ll_{C,\varepsilon}N^{-4/5+\varepsilon}+B/N.
    \label{p1:arith:badpairs}
\end{align}
In particular $\beta_N\asymp_C LN^{-2/3}$.
\end{corollary}

\begin{theorem}[Fixed factorial moments]
\label{p1:fixed:moments}
For every fixed integer \(r\ge2\) and every
\(\varepsilon>0\),
\begin{equation}
 \E(Z_N)_r
   =\mu_N^r+\binom r2\mu_N^{r-2}\alpha_N
       +O_{r,C,\varepsilon}(N^{-4/5+\varepsilon}).
 \label{p1:fixed:moment-expansion}
\end{equation}
Equivalently, one may use \(\lambda_N\) and
\(a_N=\E(Z_N)_2-\lambda_N^2\).
All fixed ordinary moments are bounded. More precisely,
with \(T_r(u)=\E[\Pois(u)^r]\),
\begin{equation}
 \E Z_N^r
    =T_r(\mu_N)+\frac{\alpha_N}{2}T_r''(\mu_N)
       +O_{r,C,\varepsilon}(N^{-4/5+\varepsilon}).
 \label{p1:fixed:ordinary}
\end{equation}
For every fixed \(r\ge3\), the \(r\)-th factorial
cumulant is \(O_{r,C,\varepsilon}(N^{-4/5+\varepsilon})\).
\end{theorem}

\begin{lemma}[A generating function with marked isolated vertices]
\label{p1:core:generator}
Let a simple graph have $n$ vertices, maximum degree $\Delta$ and
$M$ marked vertices. If $\mathcal F$ consists of the vertex sets
whose induced isolated vertices are all marked, then, for $z\ge0$,
\begin{equation}
 \sum_{D\in\mathcal F}z^{|D|}
 \le\exp\left\{Mz+nz\bigl((1+z)^\Delta-1\bigr)\right\}.
 \label{p1:core:generator-bound}
\end{equation}
More generally, for nonnegative vertex weights $w_v$ and marked set
$\mathcal M$,
\[
 \sum_{D\in\mathcal F}\prod_{v\in D}w_v
 \le \exp\left\{\sum_{v\in\mathcal M}w_v+
 \sum_vw_v\left(\prod_{u\sim v}(1+w_u)-1\right)\right\}.
\]
\end{lemma}

\begin{theorem}[Absolute activity of incompatible triples]
\label{p13:activity:incompatible}
For every \(\varepsilon>0\),
\[
 \sum_{\substack{T\subseteq\mathcal I_N,\ |T|=3\\q(T)=0}}
           |c(T)|\ll_{C,\varepsilon}N^{-3/2+\varepsilon}.
\]
Both signs of the centered coefficient are included.
\end{theorem}

\begin{proposition}[The third cumulant and the positive activity]
\label{p13:activity:kappa3}
Every compatible triple has \(c(T)\ge0\), and
\begin{equation}
 \kappa_{3,N}=6K_3^++O_{C,\varepsilon}(N^{-3/2+\varepsilon}),
 \qquad
 A_3=K_3^++O_{C,\varepsilon}(N^{-3/2+\varepsilon}).
 \label{p13:activity:kappa-comparison}
\end{equation}
In the second equality the difference \(A_3-K_3^+\)
is nonnegative.
\end{proposition}

\begin{theorem}[A uniform nonaligned rank bound]
\label{p13:rig:nonaligned}
For every fixed critical band,
\begin{equation}
 \limsup_{N\to\infty}\ 
 \sup_{\substack{x,y\in I_N\\x,y\ {\rm nonaligned}}}
             \frac{d_{xy}}B
       \le\frac23\log2<\frac12.
 \label{p13:rig:nonaligned-bound}
\end{equation}
Compatibility of the two events is not needed.
\end{theorem}

\begin{corollary}[Triple rank and maximum joint probability]
\label{p13:rig:triple}
Every compatible triple $T$ of distinct centres in the
fixed critical band satisfies
\begin{equation}
                 \rho_{\rm rel}(T)\le\frac32L+o_C(L).
 \label{p13:rig:triple-nullity}
\end{equation}
If any of its pairs is nonaligned, the stronger bound
$\rho_{\rm rel}(T)\le(1+(2/3)\log2)L+o_C(L)$ holds.
In particular, with $q(T)=\E\prod_{x\in T}J_x$,
\begin{equation}
                  \max_{\substack{T\subset I_N\\|T|=3}}q(T)
                            \le N^{-3/2+o_C(1)}.
 \label{p13:rig:max-triple}
\end{equation}
\end{corollary}

\begin{theorem}[Optimal power of the third factorial cumulant]
\label{p13:third:main}
For each fixed critical band $C>0$, there is a constant $c_C>0$ such
that, for all sufficiently large $N$,
\begin{equation}
 c_C N^{-41/30}\leq\kappa_{3,N}
              \ll_{C,\varepsilon}N^{-41/30+\varepsilon}
              \qquad(\varepsilon>0).
 \label{p13:third:two-sided}
\end{equation}
Both bounds are unconditional.  Thus $41/30$ is the optimal power
exponent for this factorial cumulant.  The theorem does not assert an
asymptotic equivalent or identify a logarithmic factor for the full
cumulant.
\end{theorem}

\begin{proposition}[Triples meeting finitely many aligned channels]
\label{p13:third:aligned-family}
Fix a finite set $\mathcal F$ of reduced interior channels $a:b$, with
$b\geq3$ and $b/2<a<b$, before $N$.  Then
\begin{equation}
 \sum_{\substack{|T|=3,\ T\ {\rm connected},\ q(T)>0\\
            \text{some pair of }T\text{ is aligned in }\mathcal F}}q(T)
       \ll_{\mathcal F,C,\varepsilon}N^{-41/30+\varepsilon}.
 \label{p13:third:aligned-family-bound}
\end{equation}
The sum allows irregular admissible windows, bad normalization of the
source pair, and contacts at distance exactly $L$.
\end{proposition}

\begin{corollary}[Strong aligned pairs]
\label{p13:third:aligned}
For every fixed $\theta>0$ and every $\varepsilon>0$,
\begin{equation}
 \sum_{\substack{|T|=3,\ T\ {\rm connected},\ q(T)>0\\
        \exists\{x,y\}\subset T\ {\rm aligned}:\ d_{xy}\geq\theta B}}
             q(T)\ll_{C,\theta,\varepsilon}N^{-41/30+\varepsilon}.
 \label{p13:third:strong-aligned-bound}
\end{equation}
\end{corollary}

\begin{proposition}[The rational lower bound]
\label{p13:third:lower}
For all sufficiently large $N$ in the critical band,
\begin{equation}
 K_3^+:=\sum_{\substack{|T|=3,\ T\ {\rm connected}\\q(T)>0}}c(T)
                  \gg_C N^{-41/30}.
 \label{p13:third:K3-lower}
\end{equation}
In particular $\kappa_{3,N}\geq c_C N^{-41/30}$ for a suitable
$c_C>0$.
\end{proposition}

\begin{corollary}[Absolute third-order activity]
\label{p13:third:activity}
For every $\varepsilon>0$,
\begin{equation}
 A_3:=\sum_{|T|=3}|c(T)|
            \ll_{C,\varepsilon}N^{-41/30+\varepsilon}.
 \label{p13:third:absolute}
\end{equation}
\end{corollary}

\begin{lemma}[Conversion with heterogeneous marginals]
\label{p13:transfer:conversion}
Let $s_j=\sum_i p_i^j$, $C_2=\sum_{|e|=2}c(e)$, and
$\alpha=2C_2-s_2$. If $\mu\leq M$ and $p_*\leq1/4$, then
\begin{equation}
 \|B_2-Q_{\mu,\alpha}\|_1
 \leq C_M\{s_3+s_2^2+A_2(s_2+p_*)\}.
 \label{p13:transfer:conversion-bound}
\end{equation}
For the present model this is $O_{C,\varepsilon}(N^{-5/3+\varepsilon})$.
\end{lemma}

\begin{lemma}[Conditional dense pair estimate]
\label{p13:transfer:dense-targets}
Fix a number $s$ of source windows and an effective subspace $W$ of
their value space. Suppose $S_y\cap W=S_z\cap W=0$, and write
\[
 d=\dim W+\dim S_y+\dim S_z-\dim(W+S_y+S_z).
\]
For every fixed $\eta,\varepsilon>0$ there exists a fixed $\theta>0$
such that, uniformly in the sources and $W$,
\begin{equation}
 \sum_{\substack{y\ne z,\ y,z\text{ outside the sources}\\
             d\geq\eta L\\
             (y,z)\text{ nonaligned or }\dim(S_y\cap S_z)\leq\theta L}}
         p_yp_z2^d\ll_{s,C,\eta,\varepsilon}N^{-1+\varepsilon}.
 \label{p13:transfer:dense-target-bound}
\end{equation}
In particular the hypothesis on the pair is satisfied when $S_y,S_z$
are direct. For a primitive family of fixed size $r\geq3$, with a
prescribed collection of $r-2$ sources having at most $N^{a+\varepsilon}$
possibilities, its dense homogeneous mass is at most
\begin{equation}
 \sum_{\rho\geq\eta L}\Bigl(\prod_{i\in I}p_i\Bigr)2^{\rho(I)}
          \ll N^{-(r-1)+a+\varepsilon}.
 \label{p13:transfer:restricted-dense}
\end{equation}
\end{lemma}

\begin{proposition}[Primitive mass at every fixed size]
\label{p13:transfer:primitive}
For every fixed integer $r\ge3$ and every $\varepsilon>0$,
\begin{equation}
 \sum_{\substack{I\subseteq\mathcal I_N,\ |I|=r\\I\ \mathrm{primitive}}}
         \Bigl(\prod_{x\in I}p_x\Bigr)2^{\rho(I)}
       \ll_{r,C,\varepsilon}N^{-r/2+\varepsilon}.
 \label{p13:transfer:primitive-bound}
\end{equation}
For each fixed $\eta>0$, primitive families with $\rho(I)\ge\eta L$
have $O_{r,C,\eta,\varepsilon}(N^\varepsilon)$ hosts and total
weight $O_{r,C,\eta,\varepsilon}(N^{1-r+\varepsilon})$.
These statements hold with exact heterogeneous marginals, including
irregular windows. The thresholds are chosen after the fixed parameters
and before $N,L$ and any deterministic subfamily being summed.
\end{proposition}

\begin{lemma}[A fixed number of extensions of a pair]
\label{p13:transfer:fixed-deficit}
For every fixed $k\geq1$,
\begin{equation}
 \sum_{|e|=2}|c(e)|
 \sum_{\substack{U\cap e=\varnothing,\ |U|=k\\
                  S_e,(S_z)_{z\in U}\text{ not direct}}}
                  \prod_{z\in U}p_z
 \ll_{k,C,\varepsilon}N^{-3/2+\varepsilon},
 \qquad S_e=\sum_{i\in e}S_i.
 \label{p13:transfer:fixed-pair-bound}
\end{equation}
\end{lemma}

\begin{proposition}[The pair deficit over all cardinalities]
\label{p13:transfer:pair-deficit}
For fixed $u>0$ and every $\varepsilon>0$,
\begin{equation}
 D_2(u)\ll_{u,C,\varepsilon}N^{-3/2+\varepsilon}.
 \label{p13:transfer:pair-deficit-bound}
\end{equation}
In particular it is smaller than the $N^{-4/3}$ scale required below.
\end{proposition}

\begin{proposition}[Reduction of connected activities]
\label{p13:transfer:fixed-activities}
For every fixed $r\geq4$ and every $\varepsilon>0$,
\begin{equation}
 \sum_{\substack{|I|=r\\I\text{ connected}}}|c(I)|
 \ll_{r,C,\varepsilon}N^\varepsilon A_3+N^{-4/3+\varepsilon}.
 \label{p13:transfer:fixed-activity-bound}
\end{equation}
The incompatible part, for every fixed $r\geq4$, is
$O_{r,C,\varepsilon}(N^{-3/2+\varepsilon})$.
\end{proposition}

\begin{proposition}[Uniform connected and primitive tails]
\label{p13:transfer:uniform-tail}
For fixed $w>0$, every $\varepsilon>0$, and every $K_N=o(L)$,
\begin{align}
 \sum_{\substack{I\text{ connected},\ 256<|I|\leq K_N\\
                         \rho^*(I)\leq2L}}
              w^{|I|}|c(I)|&\ll N^{-4/3+\varepsilon},
                    \label{p13:transfer:connected-tail}\\
 \sum_{\substack{P\text{ primitive}\\|P|>256}}
              w^{|P|}|c(P)|&\ll N^{-4/3+\varepsilon}.
                    \label{p13:transfer:primitive-tail}
\end{align}
The second sum includes all cardinalities. Here
$\rho^*(I)=\max\{\rho(A):A\subseteq I,\ q(A)>0\}$.
\end{proposition}

\begin{theorem}[Finite transfer to the complete law]
\label{p13:transfer:finite}
Fix $1<\beta\leq4/3$. Suppose that, for each of the fixed integers
$3\leq r\leq256$ and every $\varepsilon>0$,
\begin{equation}
 \sum_{\substack{|I|=r,\ I\text{ connected}\\\rho^*(I)\leq2L}}
                   |c(I)|\ll_{r,C,\varepsilon}N^{-\beta+\varepsilon}.
 \label{p13:transfer:finite-hypothesis}
\end{equation}
Then
\begin{equation}
 \|\Law(Z_N)-Q_{\mu_N,\alpha_N}\|_1
                  \ll_{C,\varepsilon}N^{-\beta+\varepsilon}.
 \label{p13:transfer:finite-conclusion}
\end{equation}
Only these $254$ fixed orders are assumed in
\eqref{p13:transfer:finite-hypothesis}; the larger orders are supplied
by Proposition~\ref{p13:transfer:uniform-tail}.
\end{theorem}

\begin{theorem}[Reconstruction from triple activity]
\label{p13:transfer:reconstruction}
With the exact mean and second factorial cumulant,
\begin{equation}
 \|\Law(Z_N)-Q_{\mu_N,\alpha_N}\|_1
       \ll_{C,\varepsilon}N^\varepsilon A_3+N^{-4/3+\varepsilon}.
 \label{p13:transfer:reconstruction-bound}
\end{equation}
In particular the arithmetic triple estimate gives the upper bound
$O_{C,\varepsilon}(N^{-4/3+\varepsilon})$ for the full model.
\end{theorem}

\begin{lemma}[The fourth factorial cumulant]
\label{p13:lower:quartic}
For every fixed critical band and every $\varepsilon>0$,
\begin{equation}
 \kappa_4=24K_4+O_{C,\varepsilon}(N^{-5/3+\varepsilon}),\qquad
 K_4=K_4^++O_{C,\varepsilon}(N^{-3/2+\varepsilon}).
 \label{p13:lower:quartic-identities}
\end{equation}
Consequently
\begin{equation}
 \kappa_4+3\alpha^2
 =3\alpha^2+24K_4^++O_{C,\varepsilon}(N^{-3/2+\varepsilon}).
 \label{p13:lower:positive-quartic}
\end{equation}
\end{lemma}

\begin{theorem}[Optimal power for the exact quadratic reference]
\label{p13:lower:optimal}
For every $C>0$ and $\varepsilon>0$, there are
$c_{C,\varepsilon}>0$ and $N_0(C,\varepsilon)$ such that
\begin{equation}
 \|\Law(Z_N)-Q_{\mu_N,\alpha_N}\|_1
 \geq c_{C,\varepsilon}N^{-4/3-\varepsilon}
 \label{p13:lower:norm}
\end{equation}
whenever $N\geq N_0$ and $|L-\log_2N|\leq C$.
Together with Theorem~\ref{p13:transfer:reconstruction} and the triple
activity bound, this identifies the optimal power as $4/3$.
It does not assert an asymptotic constant or a logarithmic factor for
the remainder.
\end{theorem}

\begin{corollary}[Every fixed polynomial weight]
\label{p13:optimal:weighted}
For every fixed integer \(m\ge0\) and \(\varepsilon>0\),
\begin{equation}
 \sum_{k\ge0}(1+k)^m
   \left|\P(Z_N=k)-Q_{\mu_N,\alpha_N}\{k\}\right|
       \ll_{C,m,\varepsilon}N^{-4/3+\varepsilon}.
 \label{p13:optimal:weighted-bound}
\end{equation}
For every fixed \(r\ge2\), consequently,
\begin{equation}
 \E(Z_N)_r
 =\mu_N^r+\binom r2\mu_N^{r-2}\alpha_N
           +O_{C,r,\varepsilon}(N^{-4/3+\varepsilon}).
 \label{p13:optimal:moments}
\end{equation}
The equalities for \(r=0,1,2\) hold without a remainder
when the right side is interpreted in its natural form.
\end{corollary}

\begin{proposition}[The quantized mean bias]
\label{p13:optimal:nominal}
Let \(\eta_x\) indicate one-window compatibility and put
\(h_x=L-\dim S_x\). Then
\begin{equation}
 \mu_N-\lambda_N=pM_{N,L},\qquad
 M_{N,L}=\sum_{x\in I_N}(\eta_x2^{h_x}-1)\in\Z.
 \label{p13:optimal:integer-mean}
\end{equation}
Thus either \(\mu_N=\lambda_N\) or
\(|\mu_N-\lambda_N|\ge p\asymp_C N^{-1}\).
Keeping the same exact \(\alpha_N\), one has
\[
 \|\Law Z_N-Q_{\lambda_N,\alpha_N}\|_1
       \ll_{C,\varepsilon}N^{-1+\varepsilon}.
\]
On every sufficiently large admissible pair \((N,L)\)
for which \(M_{N,L}\ne0\),
\begin{equation}
 \|\Law Z_N-Q_{\lambda_N,\alpha_N}\|_1
       \asymp_C|\mu_N-\lambda_N|.
 \label{p13:optimal:nominal-distance}
\end{equation}
No assertion that \(M_{N,L}\ne0\) at infinitely many
scales is included.
\end{proposition}

\begin{theorem}[The optimal error of every fixed height truncation]
\label{p13:channels:hierarchy}
Fix $h\geq3$ and $C>0$, and write $b=h+1$ and $r=L\bmod b$.
For every $\varepsilon>0$, uniformly in the critical band,
\begin{align}
 \alpha_N-\widehat\alpha_N^{(\leq h)}
  &=\frac{\lambda_N^2}{N}T_b(L)
       +O_{h,C,\varepsilon}(N^{-b/(b+1)+\varepsilon}),
       \label{p13:channels:cumulant-remainder}\\
 \Law(Z_N)-Q_{\lambda_N,\widehat\alpha_N^{(\leq h)}}
  &=\frac{\lambda_N^2T_b(L)}{2N}\Pi_{\lambda_N}*\Delta^{*2}
       +O_{\ell^1,h,C,\varepsilon}(N^{-b/(b+1)+\varepsilon}).
       \label{p13:channels:law-remainder}
\end{align}
Define the positive number
\begin{equation}
 c_b(r)=\frac{b+r-1}{b^2\,2^{r/b}}
       \sum_{\substack{b/2<a<b\\(a,b)=1}}
                    \frac{(2a-b)(b-a)}a .
 \label{p13:channels:phase-constant}
\end{equation}
The reference is a probability measure for all sufficiently large $N$, and
\begin{equation}
 \TV\bigl(\Law(Z_N),Q_{\lambda_N,\widehat\alpha_N^{(\leq h)}}\bigr)
 \sim \frac{c_b(r)}4\lambda_N^{2-1/b}
       \|\Pi_{\lambda_N}*\Delta^{*2}\|_1\,
       L N^{-1+1/b}.
 \label{p13:channels:tv-equivalent}
\end{equation}
The ratio tends to one uniformly over the critical band with the displayed
moving parameters retained.  Thus the optimal power exponent of this
specified reference is $h/(h+1)$.
\end{theorem}

\begin{lemma}[Weighted nonaligned pairs]
\label{p13:channels:weighted-nonaligned}
For every $\varepsilon>0$,
\begin{equation}
 \sum_{\substack{x,y\in G_N,\ |x-y|>L\\(x,y)\ {\rm nonaligned}}}
             (2^{\rho(x,y)}-1)
       \ll_{C,\varepsilon}N^{1+\varepsilon}.
 \label{p13:channels:nonaligned-weight}
\end{equation}
Consequently the sum of the absolute covariances on these pairs is
$O_{C,\varepsilon}(N^{-1+\varepsilon})$.
\end{lemma}

\begin{corollary}[The error of the two-channel reference]
\label{p13:channels:height-five}
Write $L=5q+r$, $0\leq r<5$, and, for $q\geq1$, set
\begin{equation}
 \begin{split}
 M_5(N,L)&=\frac{\lambda_N^2}{N}
             \left\{\frac2{15}S_{3,5}(L)+\frac3{10}S_{4,5}(L)\right\}\\
 &=\frac{\lambda_N^2}{30N}
   \left\{2^{q-1}\bigl[17(r+4)q+13r^2+87r+620\bigr]
                              -113L-127\right\}.
 \end{split}
 \label{p13:channels:M5}
\end{equation}
Then
\begin{align}
 \Law(Z_N)-Q_{\lambda_N,\widehat\alpha_N}
   &=\frac{M_5(N,L)}2\Pi_{\lambda_N}*\Delta^{*2}
                +O_{\ell^1,C,\varepsilon}(N^{-5/6+\varepsilon}),
                \label{p13:channels:two-channel-law}\\
 \TV(\Law(Z_N),Q_{\lambda_N,\widehat\alpha_N})
   &\sim\frac{17(r+4)}{1200\,2^{r/5}}\lambda_N^{9/5}
       \|\Pi_{\lambda_N}*\Delta^{*2}\|_1\,L N^{-4/5}.
                \label{p13:channels:two-channel-tv}
\end{align}
The four-channel coefficient is
$\widehat\alpha_N^{(\leq5)}=\widehat\alpha_N+M_5(N,L)$.
Its reference has optimal exponent $5/6$, with leading phase constant
$c_6(r)=(r+5)/(45\,2^{r/6})$, where now $r=L\bmod6$.
\end{corollary}

\begin{lemma}[Unsigned positional compound-Poisson comparison]
\label{p1:limits:vector-reference}
For every fixed integer $j\ge0$ and $\varepsilon>0$, uniformly
in the critical band,
\begin{equation}
 \sum_{\boldsymbol z\in\mathbb N^{I_N}}
 (1+|\boldsymbol z|)^j
 \big|\P((J_x)_x=\boldsymbol z)-\mathsf H_N\{\boldsymbol z\}\big|
       \ll_{C,j,\varepsilon}N^{-4/5+\varepsilon},
 \qquad |\boldsymbol z|=\sum_xz_x.
 \label{p1:limits:vector-weighted}
\end{equation}
\end{lemma}

\begin{lemma}[Two small odd kernels]\label{p1:arith:twokernel}
Uniformly for $B\asymp\log N$, fixed $0<\beta<1$, and $\varepsilon>0$,
\[
 G_2(N,N^\beta):=
 \#\{x\in I_N:\#\{n\in V_x:K_B(n)\leq N^\beta\}\geq2\}
 \ll_{\beta,C,\varepsilon}N^{\max(\beta,7/12)+\varepsilon}.
\]
For $7/12\leq\beta<1$ this exponent is sharp in the sense
$G_2(N,N^\beta)=N^{\beta+o(1)}$.
\end{lemma}

\begin{lemma}[The dense weighted sector]\label{p1:arith:dense}
For every fixed $\eta,\varepsilon>0$,
\[
 \sum_{\substack{x,y\in I_N,\ |x-y|>L\\
        (x,y)\ {\rm nonaligned},\ c(x,y)\geq\eta B}}
       (2^{\rho(x,y)}-1)
 \ll_{C,\eta,\varepsilon}N^{1+\varepsilon}.
\]
The same bound holds for the full value kernel, without block-parity rows.
\end{lemma}

\begin{proposition}[Positive Palm cost of a good edge]\label{p1:arith:palm}
For $a:b\in\{2:3,3:4\}$ let $\mathcal E_{a,b}$ be its good edges and put
$\beta_{a,b}=\sum_{e\in\mathcal E_{a,b}}q_e$.  Then
\begin{align}
 \frac1{\beta_{2,3}}\sum_{\{x,y\}\in\mathcal E_{2,3}}q_{xy}
    \sum_{z\in G_N\setminus\{x,y\}}
       (\P(J_z=1\mid J_x=J_y=1)-p)_+
   &\ll_{C,\varepsilon}N^{-2/3+\varepsilon},\label{p1:arith:palm23}\\
 \frac1{\beta_{3,4}}\sum_{\{x,y\}\in\mathcal E_{3,4}}q_{xy}
    \sum_{z\in G_N\setminus\{x,y\}}
       (\P(J_z=1\mid J_x=J_y=1)-p)_+
   &\ll_{C,\varepsilon}N^{-1/2+\varepsilon}.\label{p1:arith:palm34}
\end{align}
Consequently the unnormalised positive two-block masses are
$O_{C,\varepsilon}(N^{-4/3+\varepsilon})$ and
$O_{C,\varepsilon}(N^{-5/4+\varepsilon})$, respectively.
\end{proposition}

\begin{proposition}[Fixed primitive mass]
\label{p1:fixed:primitive}
For every fixed \(r\ge3\) and \(\varepsilon>0\),
\begin{equation}
 \sum_{\substack{(x_1,\ldots,x_r)\ {\rm primitive}\\
                  {\rm distinct,\ separated}}}
          p^r2^{\rho(x_1,\ldots,x_r)}
        \ll_{r,C,\varepsilon}N^{-4/5+\varepsilon}.
 \label{p1:fixed:primitive-bound}
\end{equation}
In particular the same estimate holds for the affine
joint probabilities of the original events.
\end{proposition}

\begin{proposition}[Fixed primitive mass after pair compression]
\label{p1:fixed:compressed}
Fix a channel \(a:b\in\{2:3,3:4\}\), and put
\(\kappa_b=2-1/b\). For every fixed \(r\ge3\), the total
homogeneous mass of primitive families consisting of
one exactly compressed pair in this channel and
\(r-1\) further original windows is
\begin{equation}
 O_{r,C,\varepsilon}
       (N^{-\kappa_b+1/5+\varepsilon}).
 \label{p1:fixed:compressed-bound}
\end{equation}
For a compressed pair and just one further original
window the corresponding masses are, respectively,
\(O_\varepsilon(N^{-4/3+\varepsilon})\) and
\(O_\varepsilon(N^{-5/4+\varepsilon})\).
The affine positive masses satisfy the same bounds.
\end{proposition}

\begin{corollary}[Dense nonaligned pairs]
\label{p13:conf:dense-pairs}
For fixed \(\eta,\varepsilon>0\), nonaligned pairs
with \(d_{xy}\ge\eta B\) have \(O(N^\varepsilon)\)
hosts.
\end{corollary}

\begin{lemma}[Absolute centred mass at a fixed order]
\label{p1:core:fixed-centred}
For every fixed integer $r\ge3$ and $\varepsilon>0$,
\begin{equation}
 \sum_{\substack{C\subseteq G_N,\ |C|=r\\C\ \mathrm{connected}}}
       |c(C)|\ll_{r,\varepsilon}N^{-4/5+\varepsilon}.
 \label{p1:core:fixed-centred-bound}
\end{equation}
The sum over all $r$-element families containing a contact, with no
connectedness restriction, is $O_{r,\varepsilon}(N^{-1+\varepsilon})$.
\end{lemma}

\begin{theorem}[Primitive families at all cardinalities]
\label{p1:core:primitive}
For every fixed $w>0$ and $\varepsilon>0$,
\begin{equation}
 \sum_{\substack{C\subseteq G_N\ \mathrm{primitive}\\|C|\ge3}}
 w^{|C|}\bigl(q(C)+|c(C)|\bigr)
 \ll_{w,\varepsilon}N^{-4/5+\varepsilon}.
 \label{p1:core:primitive-bound}
\end{equation}
The sum includes overlapping windows and incompatible affine systems.
\end{theorem}

\begin{theorem}[A distinguished compressed pair at all cardinalities]
\label{p1:core:compressed}
For fixed $w>0$, let
\[
 \mathcal P_b(w)=\sum_{\substack{(e,A)\ \mathrm{primitive\ after\ compression}\\
                  e\ \mathrm{in\ channel}\ a:b,\ |A|\ge1}}
 w^{|A|+2}\{q(e,A)+|\widehat c(e,A)|+|c(e\cup A)|\}.
\]
Then, for each $\varepsilon>0$,
\begin{align}
 \mathcal P_3^{\mathrm{sep}}(w)&\ll_{w,\varepsilon}N^{-4/3+\varepsilon},&
 \mathcal P_4^{\mathrm{sep}}(w)&\ll_{w,\varepsilon}N^{-5/4+\varepsilon},
 \label{p1:core:compressed-separated}\\
 \mathcal P_b(w)&\ll_{w,\varepsilon}N^{-1+\varepsilon},&&b=3,4.
 \label{p1:core:compressed-all}
\end{align}
The superscript restricts all original windows to be separated. The
pair remains distinguished in each sum.
\end{theorem}

\begin{theorem}[All cardinalities below two ranks]
\label{p1:core:low-nullity}
For fixed $0\le\eta<2$, $w>0$ and $\varepsilon>0$,
\begin{equation}
 \sum_{\substack{C\subseteq G_N\ \mathrm{connected},\ |C|\ge3\\
                  \rho_*(C)\le\eta L}}
 w^{|C|}|c(C)|
 \ll_{\eta,w,\varepsilon}
 N^{-\min\{4/5,\,2-\eta\}+\varepsilon}.
 \label{p1:core:low-nullity-bound}
\end{equation}
\end{theorem}

\begin{proposition}[Positive mass of high-nullity cores]
\label{p1:core:positive-core}
Fix $\eta>1$, an even integer $t\ge\eta+2$, and $v>0$. Then
\begin{equation}
 \sum_{\substack{D\ \mathrm{compatible},\ D\ t\mathrm{-core}\\
                  L/2<\rho(D)\le\eta L}}
 v^{|D|}q(D)\ll_{\eta,t,v,\varepsilon}N^{-4/5+\varepsilon}
 \label{p1:core:positive-core-bound}
\end{equation}
for every $\varepsilon>0$, with no restriction on the cardinality.
\end{proposition}

\begin{theorem}[Bounded compatible nullity on the growing range]
\label{p1:core:bounded-nullity}
For every fixed $\eta\ge0$, $w>0$, $\varepsilon>0$ and every
$K_N=o(L)$,
\begin{equation}
 \sum_{\substack{C\subseteq G_N\ \mathrm{connected}\\
          3\le|C|\le K_N,\ \rho_*(C)\le\eta L}}
 w^{|C|}|c(C)|\ll_{\eta,w,\varepsilon}N^{-4/5+\varepsilon}.
 \label{p1:core:bounded-nullity-bound}
\end{equation}
For $\eta>1$, choose a fixed even $t\ge\eta+2$ and set $d=t-2$.
The estimate holds uniformly whenever $K_N\le L/(2d)$. In particular,
for $\eta=3/2$ one may take $t=4$, $d=2$ and $K_N\le L/4$.
\end{theorem}

\begin{proposition}[Positive mass outside the retained class]
\label{p1:close:boundary-mass}
For every $K\le L/4$,
\begin{equation}
 R_K\le F+\mathfrak G+
 e^{2\mu}\bigl\{
          \exp(A_{\rm good}+A_{\rm bad}+B_K)-1-A_{\rm good}
          \bigr\}.
 \label{p1:close:boundary-inequality}
\end{equation}
Consequently, uniformly in that range,
\begin{equation}
 R_K\ll_\varepsilon
        N^{-4/5+\varepsilon}+B/N+a_N^2.
 \label{p1:close:boundary-rate}
\end{equation}
\end{proposition}

\begin{lemma}[Poisson--Charlier conversion]
\label{p1:close:conversion}
With the parameters of the critical band,
\begin{equation}
 \|\mathsf B_\beta-Q_{\mu,\alpha_G}\|_1
 \le 4|\beta_N-C_2|+
           O_C\bigl(N^{-2}+a_N/N\bigr).
 \label{p1:close:conversion-bound}
\end{equation}
\end{lemma}

\begin{theorem}[A modified count with all factorial tails]
\label{p1:limits:modified}
On the original probability space define
$\widetilde Z_N=Z_N^\circ\ind_{(E'_N)^c}$.
Then
\begin{equation}
 \TV(\Law Z_N,\Law\widetilde Z_N)
       \ll_\varepsilon N^{-4/5+\varepsilon}.
 \label{p1:limits:modified-tv}
\end{equation}
Uniformly for every integer $k\ge1$, every real $s\ge1$, and
every integer $r\ge1$,
\begin{align}
 \P(Z_N^\circ\ge k)&\le\frac{\mu^{k-1}}{(k-1)!}+\delta_N,
       \label{p1:limits:real-tail}\\
 \P(\widetilde Z_N\ge k)&\le\frac{\mu^{k-1}}{(k-1)!},
       \label{p1:limits:modified-tail}\\
 \E s^{\widetilde Z_N}&\le s(1+p(s-1))^n
                         \le s e^{(s-1)\mu},
       \label{p1:limits:modified-exponential}\\
 \E(\widetilde Z_N)_r&\le\mu^r+r\mu^{r-1}.
       \label{p1:limits:modified-moments}
\end{align}
\end{theorem}

\begin{lemma}[Branching with an explicit order dependence]
\label{p1:limits:branching}
For any $j$ old starts, let $\mathcal F_{\rm old}$ contain all
their raw sign values.  There is a deterministic exceptional set of
new starts of size at most
\[
 D_{j,N}=j(2L+1)+B\sqrt{3N}
       \exp\left(C\sqrt{m_{j,N}/\log(m_{j,N}+2)}\right),
 \qquad
 m_{j,N}=\left\lceil\pi(B)+\frac{jB\log(3N)}{\log B}\right\rceil,
\]
outside which the $L$ new relative signs are uniform and independent
of $\mathcal F_{\rm old}$.  In particular, uniformly for $1\le j\le H$,
\begin{equation}
 \log(\lambda_N+D_{j,N})
       \le\frac H2+C_C\left(h+\frac{\sqrt j\,H}{h}\right).
 \label{p1:limits:branching-uniform}
\end{equation}
If $F_k=\E(Z_N)_k$, then
\begin{equation}
 F_k\le C_C\exp\left\{
   \frac{k-2}{2}H+C_C\left(kh+\frac{k^{3/2}H}{h}\right)
                     \right\}\quad(2\le k\le H).
 \label{p1:limits:growing-moments}
\end{equation}
\end{lemma}

\begin{proposition}[A very small tail from a power threshold]
\label{p1:limits:colored-tail}
For all sufficiently large $N$ in a fixed critical band, uniformly
for every real $b\ge N^{9/10}$,
\begin{equation}
 \P(Z_N>b)\le e^{-2(\log N)^3},\qquad
 \E[Z_N^r;Z_N>b]\le e^{-(\log N)^3/2}
       \quad(r\in\mathbb N,\ 0\le r\le\log N).
 \label{p1:limits:colored-tail-bound}
\end{equation}
In particular, with $S=\sqrt{\log N\log\log N}$, the same conclusions
hold at $A_{N,c}=\lceil R_Ne^{-cS}\rceil$ for every fixed $c>0$.
The threshold may depend on $c$; no assertion is made for varying
$c=c(N)$.
\end{proposition}

\begin{proposition}[Deletion, isolation, and remaining covariances]
\label{p1:limits:erasure}
Uniformly in the critical band, for every $\varepsilon>0$,
\begin{align}
 \TV(\Law J^\flat,\mathsf U_N)
       +\TV(\Law\widehat J,\mathsf U_N)
       &\ll_\varepsilon N^{-4/5+\varepsilon},
       \label{p1:limits:erasure-tv}\\
 \sum_x\big|\E J_x^\flat-(p-\iota_x)\big|
       +\sum_x\big|\E\widehat J_x-(p-\iota_x)\big|
       &\ll_\varepsilon N^{-1+\varepsilon}.
       \label{p1:limits:erasure-intensity}
\end{align}
For a counting field $X$ put
$K_{xy}(X)=\Cov(X_x,X_y)-\ind_{\{x=y\}}\E X_x$.
Then
\begin{equation}
 \sum_{x,y}|K_{xy}(J^\flat)|+
 \sum_{x,y}|K_{xy}(\widehat J)|
       \ll_\varepsilon N^{-4/5+\varepsilon}.
 \label{p1:limits:erasure-covariance}
\end{equation}
In particular, the absolute second factorial cumulants of
$W$ and $\widehat W$ have this bound.  On the natural coupling,
\begin{align}
 0\le\beta-r_N&\le\tfrac12\E(\Xi)_2=O(a_N^2),
       \label{p1:limits:edge-occurrence}\\
 \TV(\Law W,\Law\widehat W)&\le\tfrac12\E(\Xi)_2=O(a_N^2),
       \label{p1:limits:one-all-tv}\\
 W_1(\Law W,\Law\widehat W)&\le\E(\Xi)_2=O(a_N^2).
       \label{p1:limits:one-all-wasserstein}
\end{align}
Here $a_N\asymp L N^{-2/3}$ as in the main theorem.
\end{proposition}

\begin{lemma}[Reciprocal odd-prime pivots]
\label{p1:limits:reciprocal}
As $X\to\infty$,
\begin{equation}
 \sum_{n\le X}\frac1{\kappa(n)}
       =X\exp\{-2V_X+o(\nu_X)\}.
 \label{p1:limits:reciprocal-sum}
\end{equation}
The sum over $N\le n<2N$ is
$N\exp\{-2V_N+o(\nu_N)\}$.
\end{lemma}

\begin{proposition}[Exact logarithmic cost of this forcing]
\label{p1:limits:private-exact}
For this specified signed forcing,
\begin{equation}
 \mathcal E_N=\exp\{-2V_N+o(\nu_N)\}.
 \label{p1:limits:private-exact-eq}
\end{equation}
Consequently this positive coordinate-by-coordinate cost is
not $O(N^{-\alpha})$ for any fixed $\alpha>0$.
\end{proposition}

\begin{proposition}[An obstruction for every such anchor]
\label{p1:limits:all-anchors}
For every fixed $0<a<1/10$, uniformly over these arithmetic
anchor rules,
\begin{equation}
 \mathcal E_{\iota,N}\ge
       (1-o_{C,a}(1))\,2^{-2\iota}\lambda_N^2N^{-a}.
 \label{p1:limits:anchor-lower}
\end{equation}
The same assertion with an additional factor $1/2$ holds
if, instead, the orientation is any fair randomized
function of the source word alone and only its private
pivots are changed.
\end{proposition}

\begin{proposition}[A six-vertex budget for the residual space]
\label{p1:offset:six-vertex}
For every fixed $\varepsilon>0$, there is a set of primitive triples
of total mass $O_{C,C_0,\varepsilon}(N^{-1+\varepsilon})$ outside
which every cover $D$ simultaneously satisfies
\begin{equation}
 \dim R_D\le\frac{3B-|D|}{6}
           +O_{C,C_0}(B/\log B)+O_{C,C_0,\varepsilon}(1).
 \label{p1:offset:six-vertex-bound}
\end{equation}
For fixed $\eta>0$, triples admitting some cover with
$\dim R_D\ge\eta L$ number $O_{C,C_0,\eta,\varepsilon}(N^{3/2+\varepsilon})$.
On a prescribed family of planes as in
Proposition~\ref{p1:offset:planar-components}, their number is
$O(N^{1+\varepsilon})$ and their primitive mass is
$O(N^{-1+\varepsilon})$.
\end{proposition}

\begin{proposition}[Moment decomposition and pair leakage]
\label{p1:uniform:modified-moments}
For every integer \(r\ge1\),
\begin{equation}
 \E\binom{\widetilde Z}{r}
   =\binom nrp^r-F_r-L'_r
     +\beta_N\binom{n-2}{r-2}p^{r-2}-G_r-H_r,
 \label{p1:uniform:modified-identity}
\end{equation}
where the last three terms are zero for \(r=1\).
All four deficits \(F_r,G_r,L'_r,H_r\) are
nonnegative. Moreover,
\[
 \sum_{r\ge2}2^rG_r
       \ll_\varepsilon N^{-1+\varepsilon},
 \qquad
 \sum_{r\ge2}2^rH_r=o(a_N).
\]
\end{proposition}
